import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: session validation
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  const result = await pool.query('SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()', [token]);
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid session' });
  req.user = result.rows[0];
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, min_price, max_price, sort_by, order, limit } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      baseQuery += ` AND category = $${paramIdx++}`;
    }
    if (min_price) {
      params.push(parseFloat(min_price));
      baseQuery += ` AND price >= $${paramIdx++}`;
    }
    if (max_price) {
      params.push(parseFloat(max_price));
      baseQuery += ` AND price <= $${paramIdx++}`;
    }

    // Dynamic sort - validated against allowed columns
    const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Limit with user-controlled value
    const limitVal = limit ? limit : '20';
    baseQuery += ` LIMIT ${limitVal}`;

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed', detail: err.message });
  }
});

// Admin analytics endpoint
app.get('/api/v2/admin/revenue', async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  const { start_date, end_date } = req.query;
  // Parameterized - safe
  const result = await pool.query(
    'SELECT DATE(created_at) as day, SUM(total) as revenue FROM orders WHERE created_at BETWEEN $1 AND $2 GROUP BY DATE(created_at)',
    [start_date, end_date]
  );
  res.json({ revenue: result.rows });
});

// Bulk price update
app.post('/api/v2/admin/bulk-update', async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  const { updates } = req.body; // [{id, price}]
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      await client.query('UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2', [u.price, u.id]);
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
